package in.foodcart.service;
import in.foodcart.data.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class AuthService { private final CustomerRepository customers; private final VendorRepository vendors; private final SessionRepository sessions; @Value("${app.development-otp}") String otp; public AuthService(CustomerRepository c,VendorRepository v,SessionRepository s){customers=c;vendors=v;sessions=s;} public void verifyOtp(String code){if(!otp.equals(code))throw new IllegalArgumentException("Invalid OTP");} private void validMobile(String mobile){if(mobile==null||!mobile.matches("[0-9]{10}"))throw new IllegalArgumentException("Enter a valid 10-digit mobile number.");} public String customer(String mobile,String code){validMobile(mobile);verifyOtp(code);CustomerEntity c=customers.findByMobile(mobile).orElseGet(()->{CustomerEntity x=new CustomerEntity();x.mobile=mobile;return customers.save(x);});return session(c.id,"CUSTOMER");} public String vendor(String mobile,String code){validMobile(mobile);verifyOtp(code);VendorEntity v=vendors.findByMobile(mobile).orElseThrow(()->new SecurityException("No vendor is associated with this mobile"));return session(v.id,"VENDOR");} public String actor(String header,String role){if(header==null||!header.startsWith("Bearer "))throw new SecurityException("Authentication required");SessionEntity s=sessions.findByToken(header.substring(7)).orElseThrow(()->new SecurityException("Invalid session"));if(!role.equals(s.role)||s.expiresAt.isBefore(Instant.now()))throw new SecurityException("Session expired");return s.actorId;} private String session(String id,String role){SessionEntity s=new SessionEntity();s.token=UUID.randomUUID().toString().replace("-","");s.actorId=id;s.role=role;s.expiresAt=Instant.now().plus(Duration.ofDays(30));sessions.save(s);return s.token;} }
